//! The campaign route: zone matching, step pointer, permanent-reward detection.
//!
//! The route data is bundled (`assets/campaign/campaign.json`) and generated by
//! `tools/gen_campaign.py`. There is no network update: a new route ships with a
//! new release, which keeps the app offline and auditable.

use crate::model::{L10n, ZoneAlias};
use serde::Deserialize;

/// How far ahead a zone change may jump. Keeps a waypoint trip through an old
/// zone from skipping half an act.
const LOOKAHEAD: usize = 8;
/// How far ahead a reward may complete a step. Passive points come from many
/// steps, so this stays short.
const REWARD_LOOKAHEAD: usize = 4;

pub const BUNDLED: &str = include_str!("../assets/campaign/campaign.json");

#[derive(Deserialize)]
struct RawCampaign {
    schema: u32,
    version: String,
    #[serde(default)]
    patch: String,
    #[serde(default)]
    title: Option<L10n>,
    acts: Vec<RawAct>,
    zones: Vec<RawZone>,
    steps: Vec<RawStep>,
}

#[derive(Deserialize)]
struct RawAct {
    id: u32,
    title: L10n,
    levels: [u32; 2],
}

#[derive(Deserialize)]
struct RawZone {
    id: String,
    names: Vec<String>,
    /// Russian display names, aligned with `names`.
    #[serde(default)]
    ru: Vec<String>,
    act: u32,
}

#[derive(Deserialize)]
struct RawStep {
    id: String,
    act: u32,
    zone: String,
    zones: Vec<String>,
    /// Russian spellings of `zones`, also used for matching.
    #[serde(default)]
    zones_ru: Vec<String>,
    #[serde(default)]
    zone_label: Option<L10n>,
    #[serde(default)]
    kind: String,
    #[serde(default)]
    optional: bool,
    #[serde(default)]
    level: Option<String>,
    goal: L10n,
    #[serde(default)]
    quest: Option<L10n>,
    #[serde(default)]
    rewards: Vec<RawReward>,
    #[serde(default)]
    tags: Vec<String>,
}

#[derive(Deserialize)]
struct RawReward {
    kind: String,
    #[serde(rename = "match")]
    matches: Vec<String>,
}

#[derive(Clone, Debug, PartialEq, serde::Serialize)]
pub struct Act {
    pub id: u32,
    pub title: L10n,
    pub levels: [u32; 2],
}

#[derive(Clone, Debug, PartialEq, serde::Serialize)]
pub struct Zone {
    pub id: String,
    pub names: Vec<String>,
    /// Russian display names, aligned with `names`.
    pub ru: Vec<String>,
    pub act: u32,
}

#[derive(Clone, Debug, PartialEq, serde::Serialize)]
pub struct Reward {
    pub kind: String,
    pub matches: Vec<String>,
}

#[derive(Clone, Debug, PartialEq, serde::Serialize)]
pub struct Step {
    pub id: String,
    pub act: u32,
    pub zone_id: String,
    /// English and Russian zone names: both are matched against the log.
    pub zones: Vec<String>,
    /// Zone line for the UI in both languages.
    pub zone_label: L10n,
    pub kind: String,
    pub optional: bool,
    pub level: Option<String>,
    pub goal: L10n,
    pub quest: Option<L10n>,
    pub rewards: Vec<Reward>,
    pub tags: Vec<String>,
}

/// One objective of a location: a boss, a quest step or a town conversation.
#[derive(Clone, Debug, PartialEq, serde::Serialize)]
pub struct ZoneObjective {
    pub id: String,
    pub kind: String,
    pub goal: L10n,
    pub level: Option<String>,
    pub rewards: Vec<String>,
    pub done: bool,
    pub optional: bool,
}

/// Progress of the current location, built from the route and the user's marks.
#[derive(Clone, Debug, PartialEq, serde::Serialize, Default)]
pub struct ZoneProgress {
    pub zone: String,
    pub zone_ru: String,
    pub known: bool,
    pub bosses_done: usize,
    pub bosses_total: usize,
    pub quests_done: usize,
    pub quests_total: usize,
    pub objectives: Vec<ZoneObjective>,
    /// Next unfinished objective in this location.
    pub next_goal: Option<String>,
    /// Where to go once everything is marked.
    pub next_zone: Option<String>,
}

#[derive(Clone, Debug, serde::Serialize)]
pub struct Campaign {
    pub version: String,
    pub patch: String,
    pub title: L10n,
    pub acts: Vec<Act>,
    pub zones: Vec<Zone>,
    pub steps: Vec<Step>,
}

/// Lowercase, no leading "the", single spaces: the same for step data and log lines.
pub fn normalize(name: &str) -> String {
    let lower = name.trim().to_lowercase();
    let joined = lower.split_whitespace().collect::<Vec<_>>().join(" ");
    let stripped = joined.strip_prefix("the ").unwrap_or(&joined);
    stripped.trim_matches(['"', '\'', ' ']).to_string()
}

fn contains(haystack: &[String], needle: &str) -> bool {
    haystack.iter().any(|z| normalize(z) == needle)
}

impl Campaign {
    pub fn parse(json: &str) -> Result<Campaign, String> {
        let raw: RawCampaign = serde_json::from_str(json).map_err(|e| format!("JSON кампании повреждён: {e}"))?;
        if raw.schema != 1 {
            return Err(format!("Неподдерживаемая версия схемы кампании: {}", raw.schema));
        }
        if raw.steps.is_empty() {
            return Err("Маршрут кампании пуст".into());
        }
        if raw.acts.is_empty() {
            return Err("В маршруте нет актов".into());
        }
        let mut acts = Vec::with_capacity(raw.acts.len());
        for a in raw.acts {
            if a.levels[0] == 0 || a.levels[1] < a.levels[0] {
                return Err(format!("Акт {}: неверный диапазон уровней", a.id));
            }
            if acts.iter().any(|x: &Act| x.id == a.id) {
                return Err(format!("Акт {} указан дважды", a.id));
            }
            acts.push(Act { id: a.id, title: a.title, levels: a.levels });
        }
        acts.sort_by_key(|a| a.id);

        let mut zones = Vec::with_capacity(raw.zones.len());
        for z in raw.zones {
            if z.names.is_empty() {
                return Err(format!("Зона {} без названий", z.id));
            }
            zones.push(Zone { id: z.id, names: z.names, ru: z.ru, act: z.act });
        }

        let mut steps = Vec::with_capacity(raw.steps.len());
        for s in raw.steps {
            if s.zones.is_empty() || s.goal.ru.trim().is_empty() || s.goal.en.trim().is_empty() {
                return Err(format!("Шаг {} заполнен не полностью", s.id));
            }
            if !acts.iter().any(|a| a.id == s.act) {
                return Err(format!("Шаг {} ссылается на несуществующий акт {}", s.id, s.act));
            }
            if !zones.iter().any(|z| z.id == s.zone) {
                return Err(format!("Шаг {} ссылается на несуществующую зону {}", s.id, s.zone));
            }
            if steps.iter().any(|x: &Step| x.id == s.id) {
                return Err(format!("Шаг {} указан дважды", s.id));
            }
            let mut all_zones = s.zones.clone();
            all_zones.extend(s.zones_ru.iter().filter(|n| !n.trim().is_empty()).cloned());
            let label = s
                .zone_label
                .unwrap_or_else(|| L10n { ru: all_zones.first().cloned().unwrap_or_default(), en: all_zones.first().cloned().unwrap_or_default() });
            steps.push(Step {
                id: s.id,
                act: s.act,
                zone_id: s.zone,
                zones: all_zones,
                zone_label: label,
                kind: s.kind,
                optional: s.optional,
                level: s.level,
                goal: s.goal,
                quest: s.quest,
                rewards: s.rewards.into_iter().map(|r| Reward { kind: r.kind, matches: r.matches }).collect(),
                tags: s.tags,
            });
        }
        Ok(Campaign {
            version: raw.version,
            patch: raw.patch,
            title: raw.title.unwrap_or(L10n { ru: "Кампания".into(), en: "Campaign".into() }),
            acts,
            zones,
            steps,
        })
    }

    pub fn len(&self) -> usize {
        self.steps.len()
    }

    pub fn step(&self, index: usize) -> Option<&Step> {
        self.steps.get(index)
    }

    /// `"A -> B"`, `"A / B"` and `"A"` steps: the first name is what the UI shows.
    #[allow(dead_code)]
    pub fn zone_display<'a>(&self, step: &'a Step) -> &'a str {
        step.zones.first().map(|s| s.as_str()).unwrap_or("")
    }

    /// Index of the step that belongs to this zone name (alias table applied first).
    pub fn step_for_zone(&self, raw: &str, aliases: &[ZoneAlias]) -> Option<usize> {
        let z = self.resolve(raw, aliases);
        self.steps.iter().position(|s| contains(&s.zones, &z))
    }

    /// Applies the user's alias table: a localized zone name maps to the
    /// canonical English name the route uses.
    pub fn resolve(&self, raw: &str, aliases: &[ZoneAlias]) -> String {
        let z = normalize(raw);
        if let Some(alias) = aliases.iter().find(|a| normalize(&a.alias) == z) {
            return normalize(&alias.zone);
        }
        // Localized clients write translated zone names; the route data already
        // carries Russian display names, so use them before asking the user.
        if let Some(zone) = self.zones.iter().find(|zone| {
            zone.names.iter().chain(zone.ru.iter()).any(|name| normalize(name) == z)
        }) {
            return normalize(&zone.names[0]);
        }
        z
    }

    /// Objectives of one location (bosses, quests, town talks) with progress.
    pub fn zone_progress(
        &self,
        zone_raw: &str,
        done: &[String],
        cur: usize,
        mode: &str,
        aliases: &[ZoneAlias],
    ) -> ZoneProgress {
        let canonical = self.resolve(zone_raw, aliases);
        let zone = self
            .zones
            .iter()
            .find(|zone| zone.names.iter().any(|name| normalize(name) == canonical));
        let zone_id = zone.map(|z| z.id.clone()).unwrap_or_default();
        let zone_en = zone.and_then(|z| z.names.first().cloned()).unwrap_or_else(|| canonical.clone());
        let zone_ru = zone.and_then(|z| z.ru.first().cloned()).unwrap_or_default();
        let mut objectives = Vec::new();
        for step in &self.steps {
            if !zone_id.is_empty() && step.zone_id != zone_id {
                continue;
            }
            if zone_id.is_empty() {
                break;
            }
            let is_done = done.iter().any(|id| id == &step.id);
            objectives.push(ZoneObjective {
                id: step.id.clone(),
                kind: step.kind.clone(),
                goal: step.goal.clone(),
                level: step.level.clone(),
                rewards: step.rewards.iter().map(|r| r.kind.clone()).collect(),
                done: is_done,
                optional: step.optional,
            });
        }
        let bosses_total = objectives.iter().filter(|o| o.kind == "boss").count();
        let quests_total = objectives.iter().filter(|o| o.kind == "quest").count();
        let bosses_done = objectives.iter().filter(|o| o.kind == "boss" && o.done).count();
        let quests_done = objectives.iter().filter(|o| o.kind == "quest" && o.done).count();
        let next = objectives
            .iter()
            .find(|o| !o.done && o.kind == "boss")
            .or_else(|| objectives.iter().find(|o| !o.done));
        let next_goal = next.map(|o| o.goal.ru.clone()).or_else(|| {
            if objectives.is_empty() {
                self.step(cur).map(|s| s.goal.ru.clone())
            } else {
                None
            }
        });
        let next_zone = if next.is_none() {
            self.next_destination(cur, mode).map(|s| {
                if s.zone_label.ru.is_empty() { s.zone_label.en.clone() } else { s.zone_label.ru.clone() }
            })
        } else {
            None
        };
        ZoneProgress {
            zone: zone_en,
            zone_ru,
            known: !zone_id.is_empty(),
            bosses_done,
            bosses_total,
            quests_done,
            quests_total,
            objectives,
            next_goal,
            next_zone,
        }
    }

    /// Resolves a zone the log just reported.
    ///
    /// A localized client writes translated zone names, which the alias table
    /// maps to the route. The area id (`G1_1`, `G1_town`, …) is language
    /// independent, so it is the fallback when the name is not mapped yet.
    pub fn resolve_scene(&self, scene: &str, area: Option<&str>, aliases: &[ZoneAlias]) -> String {
        let by_name = self.resolve(scene, aliases);
        if self.step_for_zone(&by_name, &[]).is_some() {
            return by_name;
        }
        if let Some(area) = area.filter(|a| !a.is_empty()) {
            let by_area = self.resolve(area, aliases);
            if self.step_for_zone(&by_area, &[]).is_some() {
                return by_area;
            }
        }
        by_name
    }

    /// Indices of the steps shown in this route mode ("all" or "must").
    pub fn view(&self, mode: &str) -> Vec<usize> {
        let v: Vec<usize> = (0..self.steps.len()).filter(|&i| mode != "must" || !self.steps[i].optional).collect();
        if v.is_empty() {
            (0..self.steps.len()).collect()
        } else {
            v
        }
    }

    fn pos(view: &[usize], cur: usize) -> usize {
        view.iter().position(|&i| i >= cur).unwrap_or(view.len() - 1)
    }

    /// Position of `cur` in `view`, snapped forward onto a shown step.
    pub fn snap(&self, cur: usize, mode: &str) -> usize {
        let v = self.view(mode);
        v[Self::pos(&v, cur.min(self.steps.len().saturating_sub(1)))]
    }

    /// `delta` shown steps forward or back.
    pub fn step_by(&self, cur: usize, delta: i64, mode: &str) -> usize {
        let v = self.view(mode);
        let p = (Self::pos(&v, cur) as i64 + delta).clamp(0, v.len() as i64 - 1);
        v[p as usize]
    }

    /// New pointer after entering `zone`, or None to stay.
    ///
    /// A portal to town only counts for the very next step: selling in the
    /// middle of a zone must not jump over the rest of it. Walking back through
    /// that portal undoes the jump.
    pub fn advance(&self, cur: usize, zone: &str, mode: &str, aliases: &[ZoneAlias]) -> Option<usize> {
        let z = self.resolve(zone, aliases);
        if z.is_empty() {
            return None;
        }
        let v = self.view(mode);
        let p = Self::pos(&v, cur);
        let s = |k: usize| &self.steps[v[k]];
        let matches = |k: usize| contains(&s(k).zones, &z);
        if matches(p) {
            return (v[p] != cur).then_some(v[p]);
        }
        if p > 0 && s(p).kind == "town" && matches(p - 1) {
            return Some(v[p - 1]);
        }
        (p + 1..v.len().min(p + 1 + LOOKAHEAD))
            .find(|&k| matches(k) && (s(k).kind != "town" || k == p + 1))
            .map(|k| v[k])
    }

    /// New pointer after a reward line from the log: the shown step after the
    /// one that grants this reward, or None to stay.
    pub fn complete(&self, cur: usize, reward: &str, mode: &str) -> Option<usize> {
        let text = reward.to_lowercase();
        let v = self.view(mode);
        let p = Self::pos(&v, cur);
        (p..v.len().min(p + REWARD_LOOKAHEAD))
            .find(|&k| self.steps[v[k]].rewards.iter().any(|r| r.matches.iter().any(|m| text.contains(&m.to_lowercase()))))
            .map(|k| v[(k + 1).min(v.len() - 1)])
    }

    /// First later shown step in a different zone: where to go once this is done.
    #[allow(dead_code)]
    pub fn next_destination(&self, cur: usize, mode: &str) -> Option<&Step> {
        let here = self.steps.get(cur)?.zones.iter().map(|z| normalize(z)).collect::<Vec<_>>();
        let v = self.view(mode);
        let p = Self::pos(&v, cur);
        v.iter().skip(p + 1).map(|&i| &self.steps[i]).find(|s| {
            !s.zones.iter().any(|z| here.contains(&normalize(z)))
        })
    }

    /// Which permanent reward (if any) this log line corresponds to, for history.
    pub fn reward_kind(&self, text: &str) -> Option<&str> {
        let lower = text.to_lowercase();
        self.steps
            .iter()
            .flat_map(|s| s.rewards.iter())
            .find(|r| r.matches.iter().any(|m| lower.contains(&m.to_lowercase())))
            .map(|r| r.kind.as_str())
    }

    /// Progress within the shown route: (position 1-based, shown total).
    #[allow(dead_code)]
    pub fn progress(&self, cur: usize, mode: &str) -> (usize, usize) {
        let v = self.view(mode);
        let p = Self::pos(&v, cur);
        (p + 1, v.len())
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    fn campaign() -> Campaign {
        Campaign::parse(BUNDLED).expect("bundled campaign parses")
    }

    fn aliases() -> Vec<ZoneAlias> {
        Vec::new()
    }

    #[test]
    fn bundled_route_is_complete() {
        let c = campaign();
        assert_eq!(c.len(), 115);
        assert_eq!(c.acts.len(), 6);
        assert_eq!(c.steps[0].id, "a1-01");
        assert_eq!(c.steps[0].act, 1);
        assert!(c.steps.iter().all(|s| !s.goal.ru.trim().is_empty()));
        assert_eq!(c.zone_display(&c.steps[0]), "The Riverbank");
    }

    #[test]
    fn follows_zone_changes() {
        let c = campaign();
        let a = aliases();
        assert_eq!(c.advance(0, "The Riverbank", "all", &a), None, "same zone, no move");
        assert_eq!(c.advance(0, "Clearfell Encampment", "all", &a), Some(1));
        assert_eq!(c.advance(1, "Clearfell", "all", &a), Some(2));
        assert_eq!(c.advance(2, "The Grelwood", "all", &a), Some(3), "leading 'the' is ignored");
        assert_eq!(c.advance(3, "Hideout", "all", &a), None);
    }

    #[test]
    fn town_portal_does_not_skip_ahead() {
        let c = campaign();
        let a = aliases();
        assert_eq!(c.advance(3, "Clearfell Encampment", "all", &a), None, "too far ahead for a town step");
        assert_eq!(c.advance(4, "Clearfell Encampment", "all", &a), Some(5));
        assert_eq!(c.advance(5, "The Red Vale", "all", &a), Some(4), "back through the portal");
    }

    #[test]
    fn localized_zone_names_work_through_the_alias_table() {
        let c = campaign();
        let a = vec![ZoneAlias { alias: "Прогалина".into(), zone: "Clearfell".into() }];
        assert_eq!(c.step_for_zone("Прогалина", &a), Some(2));
        assert_eq!(c.advance(1, "Прогалина", "all", &a), Some(2));
        assert_eq!(c.step_for_zone("Прогалина", &[]), None, "without the alias it is unknown");
        assert_eq!(c.resolve("  прогалина ", &a), "clearfell");
    }

    #[test]
    fn real_russian_zone_names_resolve() {
        let c = campaign();
        let aliases = crate::model::default_aliases();
        for (ru, en) in [
            ("Берег реки", "The Riverbank"),
            ("Лагерь Клирфелл", "Clearfell Encampment"),
            ("Клирфелл", "Clearfell"),
            ("Красная Долина", "The Red Vale"),
        ] {
            let resolved = c.resolve_scene(ru, None, &aliases);
            assert_eq!(resolved, crate::campaign::normalize(en), "{ru} must map to {en}");
            assert!(c.step_for_zone(ru, &aliases).is_some(), "{ru} must be part of the route");
        }
        // An unknown translated name falls back to the area id, which is not localized.
        let resolved = c.resolve_scene("Неизвестная зона", Some("G1_1"), &aliases);
        assert_eq!(resolved, "riverbank");
        // Without an alias the name is unknown and nothing moves.
        assert_eq!(c.advance(0, "Неизвестная зона", "all", &aliases), None);
    }

    #[test]
    fn russian_zone_labels_match_without_aliases() {
        let c = campaign();
        // Every step carries a Russian label for the UI.
        assert!(c.steps.iter().all(|s| !s.zone_label.ru.trim().is_empty()));
        assert!(c.steps.iter().all(|s| !s.zone_label.en.trim().is_empty()));
        // Russian zone names from the route data match directly, no alias table needed.
        assert_eq!(c.step_for_zone("Берег реки", &[]), Some(0));
        assert_eq!(c.advance(0, "Лагерь Клирфелл", "all", &[]), Some(1));
        assert!(c.step_for_zone("Нгакану", &[]).is_some(), "combined zone matches by its first name");
        // A combined zone shows both parts in Russian.
        let combined = c.steps.iter().find(|s| s.zone_label.en.contains("->")).expect("a combined zone");
        assert!(combined.zone_label.ru.contains('→'), "{}", combined.zone_label.ru);
    }

    #[test]
    fn rewards_complete_their_step() {
        let c = campaign();
        let cold = c.steps.iter().position(|s| s.rewards.iter().any(|r| r.kind == "cold_resistance")).unwrap();
        assert_eq!(c.complete(cold, "+10% to [Resistances|Cold Resistance].", "all"), Some(cold + 1));
        assert_eq!(c.complete(cold, "+10% к сопротивлению холоду.", "all"), Some(cold + 1));
        assert_eq!(c.complete(cold + 20, "+10% to [Resistances|Cold Resistance].", "all"), None);
        assert_eq!(c.reward_kind("You have received 2 Passive Skill Points."), Some("passive_points"));
    }

    #[test]
    fn must_mode_skips_optional_steps() {
        let c = campaign();
        let v = c.view("must");
        assert!(v.len() < c.len());
        assert!(v.iter().all(|&i| !c.steps[i].optional));
        let all = c.view("all");
        assert_eq!(all.len(), c.len());
        assert_eq!(c.snap(3, "must"), *v.iter().find(|&&i| i >= 3).unwrap());
        assert_eq!(c.step_by(0, 1, "must"), v[1]);
    }

    #[test]
    fn next_destination_points_at_the_next_zone() {
        let c = campaign();
        let next = c.next_destination(0, "all").expect("somewhere to go");
        assert_eq!(c.zone_display(next), "Clearfell Encampment");
        let (pos, total) = c.progress(0, "all");
        assert_eq!((pos, total), (1, c.len()));
    }

    #[test]
    fn zone_progress_lists_bosses_and_recommends_next() {
        let c = campaign();
        let aliases = vec![ZoneAlias { alias: "Замок Огам".into(), zone: "Ogham Manor".into() }];
        let idx = c.steps.iter().position(|s| s.id == "a1-18").unwrap();
        let zp = c.zone_progress("Замок Огам", &[], idx, "all", &aliases);
        assert!(zp.known, "alias maps the client zone");
        assert_eq!(zp.bosses_total, 1);
        assert_eq!(zp.bosses_done, 0);
        assert!(zp.next_goal.as_deref().unwrap_or("").contains("Geonor"), "{:?}", zp.next_goal);

        let done = vec!["a1-18".to_string()];
        let zp2 = c.zone_progress("Замок Огам", &done, idx, "all", &aliases);
        assert_eq!(zp2.bosses_done, 1);
        assert!(zp2.next_goal.is_none());
        assert!(zp2.next_zone.is_some(), "after the boss the route moves on");
    }

    #[test]
    fn russian_zone_names_resolve_from_the_route_data() {
        let c = campaign();
        assert_eq!(c.resolve("Деревня Огама", &[]), "ogham village");
        assert_eq!(c.resolve("Поместье Огама", &[]), "ogham manor");
    }

    #[test]
    fn broken_route_is_rejected_with_a_message() {
        assert!(Campaign::parse("{").is_err());
        assert!(Campaign::parse(r#"{"schema":2,"version":"x","acts":[],"zones":[],"steps":[]}"#).is_err());
        let bad_zone = r#"{"schema":1,"version":"v","acts":[{"id":1,"title":{"ru":"А","en":"A"},"levels":[1,2]}],
            "zones":[{"id":"z1","names":["Zone"],"act":1}],
            "steps":[{"id":"s1","act":1,"zone":"nope","zones":["Zone"],"goal":{"ru":"ц","en":"g"}}]}"#;
        assert!(Campaign::parse(bad_zone).unwrap_err().contains("зону"));
        let dup = r#"{"schema":1,"version":"v","acts":[{"id":1,"title":{"ru":"А","en":"A"},"levels":[1,2]}],
            "zones":[{"id":"z1","names":["Zone"],"act":1}],
            "steps":[{"id":"s1","act":1,"zone":"z1","zones":["Zone"],"goal":{"ru":"ц","en":"g"}},
                     {"id":"s1","act":1,"zone":"z1","zones":["Zone"],"goal":{"ru":"ц","en":"g"}}]}"#;
        assert!(Campaign::parse(dup).unwrap_err().contains("дважды"));
    }
}

